const { Given, When, Then } = require('@cucumber/cucumber');

// --- Background ---

Given('the app is loaded', function () {
  // The Before hook in world.js already loads the app.
  // This step is a no-op that satisfies the Background.
});

// --- Adding todos ---

Given('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== 0) {
    throw new Error(`Expected empty todo list, found ${items.length} items`);
  }
});

When('the user types {string} in the new todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  }));
});

Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count) {
    throw new Error(`Expected ${count} items, found ${items.length}`);
  }
});

Then('the todo list contains {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count) {
    throw new Error(`Expected ${count} items, found ${items.length}`);
  }
});

Then('the first todo has title {string} and is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length === 0) throw new Error('No todo items found');
  const first = items[0];
  const label = first.querySelector('label');
  if (label.textContent !== title) {
    throw new Error(`Expected title "${title}", found "${label.textContent}"`);
  }
  if (first.classList.contains('completed')) {
    throw new Error(`Expected todo not completed, but it is completed`);
  }
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected empty input, found "${input.value}"`);
  }
});

Then('the new todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  if (this.document.activeElement !== input) {
    throw new Error('New todo input is not focused');
  }
});

Then('the second todo has title {string} and is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length < 2) throw new Error('Expected at least 2 items');
  const second = items[1];
  const label = second.querySelector('label');
  if (label.textContent !== title) {
    throw new Error(`Expected title "${title}", found "${label.textContent}"`);
  }
  if (second.classList.contains('completed')) {
    throw new Error(`Expected todo not completed, but it is completed`);
  }
});

// --- Toggling todos ---

Given('the user has added a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  }));
});

Given('the user has completed the todo {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      const checkbox = item.querySelector('.toggle');
      if (!checkbox.checked) {
        checkbox.click();
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user clicks the toggle checkbox on todo {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      const checkbox = item.querySelector('.toggle');
      checkbox.click();
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the todo {string} is completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      if (!item.classList.contains('completed')) {
        throw new Error(`Todo "${title}" is not completed`);
      }
      const checkbox = item.querySelector('.toggle');
      if (!checkbox.checked) {
        throw new Error(`Todo "${title}" checkbox is not checked`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the todo {string} is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      if (item.classList.contains('completed')) {
        throw new Error(`Todo "${title}" is completed`);
      }
      const checkbox = item.querySelector('.toggle');
      if (checkbox.checked) {
        throw new Error(`Todo "${title}" checkbox is checked`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (!toggleAll.checked) {
    throw new Error('Toggle-all checkbox is not checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (toggleAll.checked) {
    throw new Error('Toggle-all checkbox is checked');
  }
});

// --- Mark all ---

When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.click();
});

// --- Counter and visibility ---

Then('the counter shows {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  if (counter.textContent !== text) {
    throw new Error(`Expected counter "${text}", found "${counter.textContent}"`);
  }
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  if (main.style.display !== 'none' && !main.classList.contains('hidden')) {
    // Check if it's actually visible
    const style = this.window.getComputedStyle(main);
    if (style.display !== 'none') {
      throw new Error('Main section is visible');
    }
  }
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer');
  if (footer.style.display !== 'none' && !footer.classList.contains('hidden')) {
    const style = this.window.getComputedStyle(footer);
    if (style.display !== 'none') {
      throw new Error('Footer section is visible');
    }
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none') {
    throw new Error('Main section is hidden');
  }
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none') {
    throw new Error('Footer section is hidden');
  }
});

Then('the counter number {string} is wrapped in a strong tag', function (num) {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) {
    throw new Error('No strong tag found in counter');
  }
  if (strong.textContent !== num) {
    throw new Error(`Expected strong tag with "${num}", found "${strong.textContent}"`);
  }
});

// --- Editing todos ---

When('the user double-clicks the todo {string} label', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      const event = new this.window.MouseEvent('dblclick', { bubbles: true });
      label.dispatchEvent(event);
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the todo {string} is in editing mode', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      if (!item.classList.contains('editing')) {
        throw new Error(`Todo "${title}" is not in editing mode`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the edit input for {string} is focused', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      const editInput = item.querySelector('.edit');
      if (this.document.activeElement !== editInput) {
        throw new Error(`Edit input for "${title}" is not focused`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  }));
});

When('the user types {string} in the edit input and blurs', function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    bubbles: true,
  }));
});

When('the user clears the edit input and presses Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    bubbles: true,
  }));
});

Then('the todo {string} is not in editing mode', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      if (item.classList.contains('editing')) {
        throw new Error(`Todo "${title}" is in editing mode`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

// --- Clear completed ---

When('the user clicks {string}', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      btn.click();
      return;
    }
  }
  throw new Error(`Button "${buttonText}" not found`);
});

Then('the {string} button is hidden', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      const style = this.window.getComputedStyle(btn);
      if (style.display !== 'none') {
        throw new Error(`Button "${buttonText}" is visible`);
      }
      return;
    }
  }
  // Button not found in DOM is equivalent to hidden
});

Then('the {string} button is visible', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      const style = this.window.getComputedStyle(btn);
      if (style.display === 'none') {
        throw new Error(`Button "${buttonText}" is hidden`);
      }
      return;
    }
  }
  throw new Error(`Button "${buttonText}" not found`);
});

// --- Filtering ---

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

Then('the todo list shows {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  // Only count visible items
  let visibleCount = 0;
  for (const item of items) {
    const style = this.window.getComputedStyle(item);
    if (style.display !== 'none') {
      visibleCount++;
    }
  }
  if (visibleCount !== count) {
    throw new Error(`Expected ${count} visible items, found ${visibleCount}`);
  }
});

Then('the todo list shows {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  // Only count visible items
  let visibleCount = 0;
  for (const item of items) {
    const style = this.window.getComputedStyle(item);
    if (style.display !== 'none') {
      visibleCount++;
    }
  }
  if (visibleCount !== count) {
    throw new Error(`Expected ${count} visible items, found ${visibleCount}`);
  }
});

Then('the visible todo has title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const style = this.window.getComputedStyle(item);
    if (style.display !== 'none') {
      const label = item.querySelector('label');
      if (label.textContent !== title) {
        throw new Error(`Expected visible todo "${title}", found "${label.textContent}"`);
      }
      return;
    }
  }
  throw new Error('No visible todo items');
});

Then('the {string} filter is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  for (const link of links) {
    if (link.textContent.trim() === filterName) {
      if (!link.classList.contains('selected')) {
        throw new Error(`Filter "${filterName}" is not selected`);
      }
      return;
    }
  }
  throw new Error(`Filter "${filterName}" not found`);
});

// --- DOM identity ---

Given('the DOM node reference for todo {string} is captured', function (title) {
  if (!this._capturedNodes) this._capturedNodes = {};
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label.textContent === title) {
      this._capturedNodes[title] = item;
      return;
    }
  }
  throw new Error(`Todo "${title}" not found for capture`);
});

Then('the captured DOM node for todo {string} is still attached to the document', function (title) {
  if (!this._capturedNodes || !this._capturedNodes[title]) {
    throw new Error(`No captured node for todo "${title}"`);
  }
  const node = this._capturedNodes[title];
  if (!this.document.contains(node)) {
    throw new Error(`Captured node for todo "${title}" is no longer attached to the document`);
  }
});

Then('the captured DOM node for todo {string} has class {string}', function (title, className) {
  if (!this._capturedNodes || !this._capturedNodes[title]) {
    throw new Error(`No captured node for todo "${title}"`);
  }
  const node = this._capturedNodes[title];
  if (!node.classList.contains(className)) {
    throw new Error(`Captured node for todo "${title}" does not have class "${className}"`);
  }
});

Then('the captured DOM node for todo {string} does not have class {string}', function (title, className) {
  if (!this._capturedNodes || !this._capturedNodes[title]) {
    throw new Error(`No captured node for todo "${title}"`);
  }
  const node = this._capturedNodes[title];
  if (node.classList.contains(className)) {
    throw new Error(`Captured node for todo "${title}" unexpectedly has class "${className}"`);
  }
});

// --- Persistence ---

When('the page is reloaded', async function () {
  await this.reloadApp();
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // FOCUS. happy-dom does NOT honour the autofocus attribute, so the input
    // that the spec asserts is focused on page load would never be focused.
    // Manually focus it to match real browser behaviour.
    const newTodo = this.document.querySelector('.new-todo');
    if (newTodo) newTodo.focus();

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // Reload the app while preserving localStorage state. This simulates a page refresh:
  // save the current localStorage, dispose the window, create a fresh one, restore
  // localStorage, then re-initialize the app so it loads from the persisted state.
  async reloadApp() {
    if (!this.window) throw new Error('verification support: reloadApp() before the app was loaded');
    // Snapshot the current localStorage contents
    const saved = {};
    const storage = this.window.localStorage;
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      saved[key] = storage.getItem(key);
    }
    // Dispose the current window
    await this.disposeApp();
    // Load a fresh app
    this.loadApp();
    // Restore localStorage before the app reads it
    const freshStorage = this.window.localStorage;
    Object.keys(saved).forEach(key => freshStorage.setItem(key, saved[key]));
    // Re-initialize the app so it loads from the restored state
    this.window.eval(fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8'));
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));
    const newTodo = this.document.querySelector('.new-todo');
    if (newTodo) newTodo.focus();
  }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/**
 * TodoMVC Application
 * Vanilla JavaScript implementation
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('#toggle-all');
  var todoCountElement = document.querySelector('.todo-count');
  var clearCompletedButton = document.querySelector('.clear-completed');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');
  var filterLinks = document.querySelectorAll('.filters a');

  var todos = [];
  var currentFilter = '/';

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  /** @planks("the page is reloaded") */
  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function loadTodos() {
    var stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        todos = JSON.parse(stored);
      } catch (e) {
        todos = [];
      }
    } else {
      todos = [];
    }
  }

  function getFilteredTodos() {
    switch (currentFilter) {
      case '/active':
        return todos.filter(function (todo) { return !todo.completed; });
      case '/completed':
        return todos.filter(function (todo) { return todo.completed; });
      default:
        return todos;
    }
  }

  /** @planks("the todo list contains {int} item") */
  /** @planks("the todo list contains {int} items") */
  /** @planks("the counter shows {string}") */
  /** @planks("the main section is hidden") */
  /** @planks("the footer section is hidden") */
  /** @planks("the main section is visible") */
  /** @planks("the footer section is visible") */
  /** @planks("the todo list shows {int} item") */
  /** @planks("the todo list shows {int} items") */
  function render() {
    var filteredTodos = getFilteredTodos();

    // Clear the list
    todoList.innerHTML = '';

    // Render each todo
    filteredTodos.forEach(function (todo) {
      var li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      if (todo.completed) {
        li.classList.add('completed');
      }

      var div = document.createElement('div');
      div.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyButton = document.createElement('button');
      destroyButton.className = 'destroy';

      div.appendChild(checkbox);
      div.appendChild(label);
      div.appendChild(destroyButton);

