/** @planks("the todo list shows {int} item") */
/** @planks("the todo list shows {int} items") */
/** @planks("the captured DOM node for todo {string} is still attached to the document") */
/** @planks("the captured DOM node for todo {string} has class {string}") */
/** @planks("the captured DOM node for todo {string} does not have class {string}") */
function render() {
  var filteredTodos = getFilteredTodos();

  // Build a set of IDs we need
  var neededIds = {};
  filteredTodos.forEach(function (todo) { neededIds[todo.id] = true; });

  // Remove stale <li> nodes not in the filtered set
  var existing = todoList.querySelectorAll('li[data-id]');
  for (var i = 0; i < existing.length; i++) {
    if (!neededIds[existing[i].getAttribute('data-id')]) {
      existing[i].parentNode.removeChild(existing[i]);
    }
  }

  // Render each todo, mutating existing nodes in place
  filteredTodos.forEach(function (todo) {
    var li = todoList.querySelector('li[data-id="' + todo.id + '"]');
    if (!li) {
      // Create new node
      li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      var div = document.createElement('div');
      div.className = 'view';
      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      var label = document.createElement('label');
      var destroyButton = document.createElement('button');
      destroyButton.className = 'destroy';
      div.appendChild(checkbox);
      div.appendChild(label);
      div.appendChild(destroyButton);
      var editInput = document.createElement('input');
      editInput.className = 'edit';
      li.appendChild(div);
      li.appendChild(editInput);
      todoList.appendChild(li);
    }
    // Update in place: class, checkbox, labels
    if (todo.completed) {
      li.classList.add('completed');
    } else {
      li.classList.remove('completed');
    }
    li.querySelector('.toggle').checked = todo.completed;
    li.querySelector('label').textContent = todo.title;
    li.querySelector('.edit').value = todo.title;
  });

